import sys

if hasattr(sys, "set_int_max_str_digits"):
    try:
        sys.set_int_max_str_digits(0)
    except Exception:
        pass

_WS = " \t\n\r"


def _parse_hex4(s, i):
    c = s[i]
    if "0" <= c <= "9":
        v = ord(c) - 48
    elif "a" <= c <= "f":
        v = ord(c) - 87
    elif "A" <= c <= "F":
        v = ord(c) - 55
    else:
        raise ValueError("invalid hexadecimal digit")

    c = s[i + 1]
    if "0" <= c <= "9":
        d = ord(c) - 48
    elif "a" <= c <= "f":
        d = ord(c) - 87
    elif "A" <= c <= "F":
        d = ord(c) - 55
    else:
        raise ValueError("invalid hexadecimal digit")
    v = (v << 4) | d

    c = s[i + 2]
    if "0" <= c <= "9":
        d = ord(c) - 48
    elif "a" <= c <= "f":
        d = ord(c) - 87
    elif "A" <= c <= "F":
        d = ord(c) - 55
    else:
        raise ValueError("invalid hexadecimal digit")
    v = (v << 4) | d

    c = s[i + 3]
    if "0" <= c <= "9":
        d = ord(c) - 48
    elif "a" <= c <= "f":
        d = ord(c) - 87
    elif "A" <= c <= "F":
        d = ord(c) - 55
    else:
        raise ValueError("invalid hexadecimal digit")
    v = (v << 4) | d

    return v, i + 4


def _parse_string(s, i):
    i += 1
    n = len(s)
    parts = []

    while True:
        start = i

        while i < n:
            ch = s[i]
            if ch == '"' or ch == "\\":
                break
            if ch < " ":
                raise ValueError("unescaped control character")
            if "\ud800" <= ch <= "\udfff":
                raise ValueError("unescaped surrogate")
            i += 1

        if i > start:
            parts.append(s[start:i])

        if i >= n:
            raise ValueError("unterminated string")

        ch = s[i]
        if ch == '"':
            return "".join(parts), i + 1

        if i + 1 >= n:
            raise ValueError("invalid escape")

        i += 1
        esc = s[i]
        i += 1

        if esc == '"':
            parts.append('"')
        elif esc == "\\":
            parts.append("\\")
        elif esc == "/":
            parts.append("/")
        elif esc == "b":
            parts.append("\b")
        elif esc == "f":
            parts.append("\f")
        elif esc == "n":
            parts.append("\n")
        elif esc == "r":
            parts.append("\r")
        elif esc == "t":
            parts.append("\t")
        elif esc == "u":
            if i + 4 > n:
                raise ValueError("short unicode escape")

            code, i = _parse_hex4(s, i)

            if 0xD800 <= code <= 0xDBFF:
                if i + 6 > n:
                    raise ValueError("unpaired surrogate")
                if s[i] != "\\" or s[i + 1] != "u":
                    raise ValueError("unpaired surrogate")

                code2, i = _parse_hex4(s, i + 2)

                if 0xDC00 <= code2 <= 0xDFFF:
                    cp = 0x10000 + ((code - 0xD800) << 10) + (code2 - 0xDC00)
                    parts.append(chr(cp))
                else:
                    raise ValueError("unpaired surrogate")

            elif 0xDC00 <= code <= 0xDFFF:
                raise ValueError("unpaired surrogate")

            else:
                parts.append(chr(code))
        else:
            raise ValueError("invalid escape")


def _parse_number(s, i):
    n = len(s)
    start = i

    if i < n and s[i] == "-":
        i += 1

    if i >= n:
        raise ValueError("invalid number")

    c = s[i]

    if c == "0":
        i += 1
        if i < n and "0" <= s[i] <= "9":
            raise ValueError("invalid number")
    elif "1" <= c <= "9":
        i += 1
        while i < n and "0" <= s[i] <= "9":
            i += 1
    else:
        raise ValueError("invalid number")

    is_float = False

    if i < n and s[i] == ".":
        is_float = True
        i += 1
        if i >= n or not ("0" <= s[i] <= "9"):
            raise ValueError("invalid number")
        while i < n and "0" <= s[i] <= "9":
            i += 1

    if i < n and (s[i] == "e" or s[i] == "E"):
        is_float = True
        i += 1
        if i < n and (s[i] == "+" or s[i] == "-"):
            i += 1
        if i >= n or not ("0" <= s[i] <= "9"):
            raise ValueError("invalid number")
        while i < n and "0" <= s[i] <= "9":
            i += 1

    raw = s[start:i]

    if not is_float:
        return int(raw), i

    return float(raw), i


def _parse_literal(s, i):
    c = s[i]

    if c == "t":
        if not s.startswith("true", i):
            raise ValueError("invalid literal")
        return True, i + 4

    if c == "f":
        if not s.startswith("false", i):
            raise ValueError("invalid literal")
        return False, i + 5

    if c == "n":
        if not s.startswith("null", i):
            raise ValueError("invalid literal")
        return None, i + 4

    if c == '"':
        return _parse_string(s, i)

    if c == "-" or ("0" <= c <= "9"):
        return _parse_number(s, i)

    raise ValueError("invalid value")


def parse_json(text: str) -> object:
    s = text
    n = len(s)
    pos = 0

    while pos < n and s[pos] in _WS:
        pos += 1

    if pos >= n:
        raise ValueError("empty JSON text")

    stack = []
    top_value = None
    done = False

    def put_value(value):
        nonlocal top_value, done

        if not stack:
            top_value = value
            done = True
            return

        parent = stack[-1]

        if parent[0] == 0:  # array
            parent[1].append(value)
            parent[2] = 2   # after
        else:              # object
            obj = parent[1]
            key = parent[3]
            if key in obj:
                raise ValueError("duplicate key")
            obj[key] = value
            parent[2] = 3   # after

    while True:
        while pos < n and s[pos] in _WS:
            pos += 1

        if pos >= n:
            if done:
                return top_value
            raise ValueError("incomplete JSON text")

        if not stack:
            if done:
                raise ValueError("unexpected trailing text")

            c = s[pos]

            if c == "{":
                if len(stack) >= 50000:
                    raise ValueError("nesting depth limit exceeded")
                stack.append([1, {}, 0, None])
                pos += 1
                continue

            if c == "[":
                if len(stack) >= 50000:
                    raise ValueError("nesting depth limit exceeded")
                stack.append([0, [], 0, None])
                pos += 1
                continue

            top_value, pos = _parse_literal(s, pos)
            done = True
            continue

        frame = stack[-1]
        kind = frame[0]
        state = frame[2]
        c = s[pos]

        if kind == 0:  # array
            if state == 2:  # after
                if c == ",":
                    pos += 1
                    frame[2] = 1  # value
                    continue

                if c == "]":
                    pos += 1
                    completed = frame[1]
                    stack.pop()
                    put_value(completed)
                    continue

                raise ValueError("invalid array separator")

            if state == 0 and c == "]":
                pos += 1
                completed = frame[1]
                stack.pop()
                put_value(completed)
                continue

            if c == "{":
                if len(stack) >= 50000:
                    raise ValueError("nesting depth limit exceeded")
                stack.append([1, {}, 0, None])
                pos += 1
                continue

            if c == "[":
                if len(stack) >= 50000:
                    raise ValueError("nesting depth limit exceeded")
                stack.append([0, [], 0, None])
                pos += 1
                continue

            value, pos = _parse_literal(s, pos)
            put_value(value)
            continue

        # object
        if state == 3:  # after
            if c == ",":
                pos += 1
                frame[2] = 1  # key
                continue

            if c == "}":
                pos += 1
                completed = frame[1]
                stack.pop()
                put_value(completed)
                continue

            raise ValueError("invalid object separator")

        if state == 0 and c == "}":
            pos += 1
            completed = frame[1]
            stack.pop()
            put_value(completed)
            continue

        if state == 0 or state == 1:  # expect key
            if c != '"':
                raise ValueError("object key must be string")

            key, pos = _parse_string(s, pos)
            frame[3] = key
            frame[2] = 2  # value
            continue

        if state == 2:  # value
            if c == "{":
                if len(stack) >= 50000:
                    raise ValueError("nesting depth limit exceeded")
                stack.append([1, {}, 0, None])
                pos += 1
                continue

            if c == "[":
                if len(stack) >= 50000:
                    raise ValueError("nesting depth limit exceeded")
                stack.append([0, [], 0, None])
                pos += 1
                continue

            value, pos = _parse_literal(s, pos)
            put_value(value)
            continue
